#!/usr/bin/env python3
"""Render a validated ops-audit roadmap as one offline, untrusted-data-safe page."""
from __future__ import annotations
import html
import json
import sys
from pathlib import Path
from validator import validate_roadmap


def esc(value): return html.escape(str(value), quote=True)
def script_json(value): return json.dumps(value, ensure_ascii=False).replace("</", "<\\/")
def list_items(items): return "<ul class=\"clean\">" + "".join(f"<li>{esc(item)}</li>" for item in items) + "</ul>" if items else "<p class=\"none\">None observed.</p>"


def card_html(card, first_move, first_automation):
    path = card["causal_path"]
    coverage = card["existing_coverage"]
    is_first_move = card["id"] == first_move
    label = "First move" if is_first_move else ("First automation" if card["id"] == first_automation else "Action")
    label_class = " first-move" if is_first_move else (" first-automation" if card["id"] == first_automation else "")
    card_class = " first-move-card" if is_first_move else ""
    costs = "<span class=\"unknown\">UNKNOWN</span>" if card["hours_per_month"] is None else f"{esc(card['hours_per_month'])} hours/month; {esc(card['annual_labor_value'])} annual labor value"
    evidence = "".join(f"<li><strong>{esc(item['label'])}:</strong> {esc(item['claim'])} <span class=\"source\">({esc(item['source'])})</span></li>" for item in card["evidence"])
    causal = "".join(f"<li><strong>{esc(name.replace('_', ' '))}:</strong> {esc(path[name])}</li>" for name in ("trigger", "collection", "judgment", "action", "destination", "read_back", "failure_visibility"))
    approval = "<span class=\"quiet\">No approval gate required.</span>" if not card["approval"]["required"] else f"<span class=\"decision-needed\">Decision needed</span> {esc(card['approval']['approver'])}: {esc(card['approval']['gate'])}"
    return f'''<article class="route-card{card_class}" data-card-id="{esc(card['id'])}" data-version="{esc(card['version'])}">
<div class="card-meta"><span class="action-label{label_class}">{label}</span><span>{esc(card['id'])} · V{esc(card['version'])}</span></div>
<h3>{esc(card['action'])}</h3>
<div class="definition-grid"><p><b>Verdict</b><span>{esc(card['verdict'])}.</span></p><p><b>Intervention</b><span>{esc(card['intervention'])}.</span></p><p><b>Diagnosis</b><span>{esc(card['diagnosis'])}</span></p><p class="cost"><b>Cost</b><span>{costs}</span></p></div>
<details><summary>Causal path</summary><div class="detail-content"><ul class="clean">{causal}</ul></div></details><details class="coverage"><summary>Existing automation coverage</summary><div class="detail-content"><h4>Definitions</h4>{list_items(coverage['definitions'])}<h4>Recent runs</h4>{list_items(coverage['recent_runs'])}<h4>Outputs</h4>{list_items(coverage['outputs'])}<h4>Failure visibility</h4>{list_items(coverage['failure_visibility'])}</div></details>
<details><summary>Evidence and gaps</summary><div class="detail-content"><ul class="clean">{evidence}</ul><h4>Gaps</h4>{list_items(card['gaps'])}</div></details>
<div class="definition-grid closing"><p><b>Approval / gate</b><span>{approval}</span></p></div><p class="proof"><b>Proof</b><span>{esc(card['proof'])}</span></p>
<fieldset><legend>Feedback for this action</legend><div class="choices"><label><input type="radio" name="choice-{esc(card['id'])}" value="accept"> Accept</label><label><input type="radio" name="choice-{esc(card['id'])}" value="change"> Change</label><label><input type="radio" name="choice-{esc(card['id'])}" value="reject"> Reject</label></div><label class="note-label">Change note — required when “change”<textarea aria-label="Change note for {esc(card['id'])}"></textarea></label></fieldset></article>'''


def main():
    if len(sys.argv) != 2: raise SystemExit("usage: render.py roadmap.json")
    roadmap = validate_roadmap(json.loads(Path(sys.argv[1]).read_text(encoding="utf-8")))
    header = f'''<header class="chart-head"><span>OPS-AUDIT · {esc(roadmap['roadmap_id'])}</span><span>Operations roadmap</span><span>{esc(roadmap['business'])} · {esc(roadmap['date'])} · REV {esc(roadmap['revision'])}</span></header>'''
    footer = f'''<footer class="chart-foot">ROADMAP {esc(roadmap['roadmap_id'])} · REV {esc(roadmap['revision'])} · GENERATED {esc(roadmap['date'])} · OFFLINE ARTIFACT</footer>'''
    if roadmap["incomplete"]:
        body = f'''<section class="partial" aria-labelledby="partial-title"><p class="incomplete-tag">Audit incomplete · stopped</p><h2 id="partial-title">Audit incomplete</h2><p>Stopped at: {esc(roadmap['stopping_point'])}</p><p>No recommendations, first move, or automation are available until the audit resumes.</p><h3>Unavailable sections</h3><ul class="clean"><li>Now / Next / Later recommendations</li><li>First move and first automation</li><li>Cost totals and feedback controls</li></ul></section>'''
    else:
        known_hours = sum(card["hours_per_month"] for card in roadmap["cards"] if card["hours_per_month"] is not None)
        annual = sum(card["annual_labor_value"] for card in roadmap["cards"] if card["annual_labor_value"] is not None)
        unknown = sum(card["hours_per_month"] is None for card in roadmap["cards"])
        first_auto = roadmap["first_automation"] or "none — " + roadmap["first_automation_reason"]
        groups = "".join(f'<section class="waypoint-group {group.lower()}" aria-labelledby="{group}"><p class="group-code">WP-{group.upper()}</p><h2 id="{group}">{group}</h2>' + "".join(card_html(card, roadmap["first_move"], roadmap["first_automation"]) for card in roadmap["cards"] if card["group"] == group) + ("" if any(card["group"] == group for card in roadmap["cards"]) else "<p class=\"empty-group\">No actions in this group.</p>") + "</section>" for group in ("Now", "Next", "Later"))
        body = f'''<section class="summary-strip"><h1>Operations roadmap</h1><div class="route-rule"></div><p class="summary-line first"><b>First move</b><span>{esc(roadmap['first_move'])}</span></p><p class="summary-line"><b>First automation</b><span>{esc(first_auto)}</span></p><div class="metrics"><div class="metric"><span class="value">{esc(known_hours)}</span><span class="label">Known hrs / mo</span></div><div class="metric"><span class="value">{esc(annual)}</span><span class="label">Annual labor burden</span></div><div class="metric{' caution' if unknown else ''}"><span class="value">{esc(unknown)}</span><span class="label">Unknown-cost count</span></div></div></section>{groups}<section class="feedback-actions"><button id="copy" type="button">Copy feedback for agent</button><p id="status" role="status" aria-live="polite"></p><label id="fallback-label" hidden>Clipboard fallback — select this text<textarea id="fallback" aria-label="Feedback text"></textarea></label><button id="clear-fallback" type="button" hidden>Clear saved feedback</button></section>'''
    data = script_json({"roadmapId": roadmap["roadmap_id"], "business": roadmap["business"], "date": roadmap["date"], "revision": roadmap["revision"], "cards": {card["id"]: card["version"] for card in roadmap["cards"]}})
    js = '''const ROADMAP = %s, KEY = 'ops-audit-feedback-' + ROADMAP.roadmapId;
const status = document.getElementById('status'), copyButton = document.getElementById('copy'), fallback = document.getElementById('fallback'), fallbackLabel = document.getElementById('fallback-label'), clearFallback = document.getElementById('clear-fallback');
function message(text, kind){status.textContent=text;status.className=kind||'';}
function clearSaved(){try{localStorage.removeItem(KEY);}catch(e){} }
function save(){const cards={};document.querySelectorAll('article').forEach(a=>{const checked=a.querySelector('input:checked'),note=a.querySelector('textarea').value;if(checked||note)cards[a.dataset.cardId]={version:Number(a.dataset.version),choice:checked&&checked.value,note:note};});try{localStorage.setItem(KEY,JSON.stringify({roadmapRevision:ROADMAP.revision,cards:cards}));}catch(e){message('Browser storage is unavailable; feedback can still be copied.','error');}}
''' % data
    # Keep restore simple and safe; split from static data to avoid selectors derived from untrusted data.
    js += '''function restoreFeedback(){try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(saved.roadmapRevision!==ROADMAP.revision||!saved.cards)return;document.querySelectorAll('article').forEach(a=>{const value=saved.cards[a.dataset.cardId];if(!value||value.version!==Number(a.dataset.version))return;const radio=value.choice&&a.querySelector('input[value="'+value.choice+'"]');if(radio)radio.checked=true;a.querySelector('textarea').value=value.note||'';});}catch(e){message('Browser storage is unavailable; feedback can still be copied.','error');}}
function showFallback(text,textMessage){fallback.value=text;fallback.hidden=false;fallbackLabel.hidden=false;clearFallback.hidden=false;message(textMessage,'error');}
function feedback(){let lines=[],blocked=null;document.querySelectorAll('article').forEach(a=>{const selected=a.querySelector('input:checked'),note=a.querySelector('textarea').value.replace(/[\\r\\n]+/g,' ').trim();a.querySelector('textarea').className='';if(selected){if(selected.value==='change'&&!note){blocked=a;return;}lines.push('- card '+a.dataset.cardId+' version '+a.dataset.version+': '+selected.value+' | note: '+note);}});if(blocked){const area=blocked.querySelector('textarea');area.className='error';message('A change requires a note before feedback can be copied.','error');area.focus();return;}if(!lines.length){message('Select feedback before copying.','error');return;}const text='Feedback on roadmap '+ROADMAP.roadmapId+' revision '+ROADMAP.revision+'.\\nUpdate the ledger, then resume the audit to apply the requested semantic change and re-render.\\n'+lines.join('\\n');if(!navigator.clipboard){showFallback(text,'Clipboard is unavailable; select the text below, then clear saved feedback when finished.');return;}navigator.clipboard.writeText(text).then(()=>{clearSaved();message('✓ Copied pending feedback. Resume the audit to apply it.','success');}).catch(()=>showFallback(text,'Copy failed; select the text below, then clear saved feedback when finished.'));}
if(copyButton){restoreFeedback();document.addEventListener('input',save);document.addEventListener('change',save);copyButton.addEventListener('click',feedback);clearFallback.addEventListener('click',()=>{clearSaved();fallback.value='';fallback.hidden=true;fallbackLabel.hidden=true;clearFallback.hidden=true;message('Saved feedback cleared.','success');});}'''
    css = '''<style>:root{--paper:#FFFCF0;--ink:#100F0F;--route:#BC5215;--route-hi:#DA702C;--red:#AF3029;--yellow:#AD8301;--green:#66800B;--cyan:#24837B;--purple:#5E409D;--soft:rgba(16,15,15,.62);--rule:rgba(16,15,15,.22);--hair:rgba(16,15,15,.10);--wash:rgba(16,15,15,.035);--serif:"Fraunces","Iowan Old Style",Palatino,Georgia,serif;--mono:"IBM Plex Mono",ui-monospace,"SF Mono",Menlo,monospace}*{box-sizing:border-box}html{background:var(--paper)}body{max-width:46rem;margin:0 auto;padding:2rem 1.25rem 4rem;background:var(--paper);color:var(--ink);font:400 16px/1.5 var(--serif);font-variant-numeric:tabular-nums;border:1px solid var(--ink)}h1,h2,h3,p{margin-top:0}h1{font:720 clamp(28px,6vw,44px)/1 var(--serif);letter-spacing:-.03em;margin:1.8rem 0 1rem}h2{font:700 clamp(24px,5vw,27px)/1.05 var(--serif);letter-spacing:-.025em;margin:0 0 1rem}h3{font:700 18px/1.2 var(--serif);margin:1rem 0}.chart-head,.chart-foot{font:500 11px/1.35 var(--mono);letter-spacing:.1em;text-transform:uppercase}.chart-head{display:grid;grid-template-columns:1fr 1fr 1fr;gap:.5rem;padding-bottom:.6rem;border-bottom:1px solid var(--ink)}.chart-head span:nth-child(2){text-align:center}.chart-head span:last-child{text-align:right}.chart-foot{border-top:1px solid var(--ink);margin-top:3.5rem;padding-top:.7rem;color:var(--soft)}.route-rule{height:3px;background:linear-gradient(90deg,var(--route) 0 31%,var(--rule) 31%);margin:1rem 0 1.4rem;position:relative}.route-rule:after{content:"";position:absolute;left:30%;top:-4px;width:9px;height:9px;border:2px solid var(--route);transform:rotate(45deg);background:var(--paper)}.summary-line{display:grid;grid-template-columns:8rem 1fr;gap:.75rem;margin:.35rem 0}.summary-line b,.definition-grid b,.proof b{font:600 11px/1.35 var(--mono);letter-spacing:.11em;text-transform:uppercase;color:var(--soft)}.summary-line.first span:before{content:"◆";font-size:.7em;color:var(--route);margin-right:.45rem}.metrics{display:grid;grid-template-columns:repeat(3,minmax(9rem,1fr));gap:.75rem;margin:1.5rem 0}.metric{border-top:2px solid var(--ink);padding-top:.55rem}.metric .value{display:block;font:650 28px/1 var(--serif)}.metric .label,.group-code,.empty-group,.incomplete-tag{font:500 11px/1.35 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--soft)}.metric.caution .value{color:var(--yellow)}.waypoint-group{margin-top:3.5rem}.waypoint-group.now{border-left:2px solid var(--route);padding-left:1rem}.group-code{margin-bottom:.25rem}.now .group-code:before,.next .group-code:before,.later .group-code:before{content:"";display:inline-block;width:7px;height:7px;margin-right:.5rem;background:var(--route)}.next .group-code:before{background:var(--ink)}.later .group-code:before{background:var(--soft)}.route-card{border:1px solid var(--rule);padding:1.1rem 1.25rem;margin:1.25rem 0;background:var(--paper)}.first-move-card{border-color:var(--ink);box-shadow:5px 5px 0 var(--route-hi)}.card-meta{display:flex;justify-content:space-between;gap:1rem;align-items:start;font:500 11px/1.2 var(--mono);letter-spacing:.1em;color:var(--soft);text-transform:uppercase}.action-label{font:600 11px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--ink);border-left:3px solid var(--rule);padding:5px 8px;background:var(--wash)}.action-label.first-move{border-left-color:var(--route)}.action-label.first-automation{border-left-color:var(--cyan)}.definition-grid p{display:grid;grid-template-columns:7.5em 1fr;gap:1rem;border-top:1px solid var(--hair);padding:.55rem 0;margin:0}.definition-grid .cost span{font-family:var(--mono)}.unknown{color:var(--yellow);font-weight:600}.quiet{color:var(--soft)}.decision-needed{display:inline-block;border-left:3px solid var(--purple);padding-left:.45rem;color:var(--purple);font:600 11px/1.3 var(--mono);letter-spacing:.08em;text-transform:uppercase}.proof{display:grid;grid-template-columns:7.5em 1fr;gap:1rem;border-top:1px solid var(--rule);padding-top:.65rem;margin:.75rem 0 0;font:500 11px/1.4 var(--mono);color:var(--soft)}details{border-top:1px solid var(--hair);padding:.6rem 0}summary{list-style:none;cursor:pointer;font:600 12px/1.5 var(--mono);letter-spacing:.1em;text-transform:uppercase}summary::-webkit-details-marker{display:none}summary:before{content:"";display:inline-block;width:7px;height:7px;border:1.5px solid var(--ink);transform:rotate(45deg);margin:0 .7rem .08rem .15rem}details[open] summary:before{background:var(--route)}.coverage summary{color:var(--cyan)}.detail-content{margin:.7rem 0 0 1.1rem;padding-left:1rem;border-left:1px solid var(--hair)}h4{font:600 11px/1.35 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--soft);margin:1rem 0 .25rem}.clean{list-style:none;padding:0;margin:.3rem 0}.clean li{position:relative;padding:.45rem 0 .45rem 1.1rem;border-top:1px solid var(--hair)}.clean li:before{content:"";position:absolute;left:.15rem;top:.85rem;width:5px;height:5px;border:1px solid var(--ink);transform:rotate(45deg)}.clean strong{font:600 11px var(--mono);letter-spacing:.04em;text-transform:uppercase}.source{font:400 11px var(--mono);color:var(--soft)}.none{color:var(--soft);font:400 13px var(--mono)}fieldset{border:0;border-top:1px solid var(--rule);padding:.9rem 0 0;margin:1rem 0 0}legend{padding:0;font:500 11px/1.35 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--soft)}.choices{display:flex;flex-wrap:wrap;gap:.5rem;margin:.6rem 0}.choices label{display:flex;align-items:center;gap:.35rem;min-height:44px;border:1px solid var(--rule);padding:.4rem .9rem;font:500 13px var(--mono);letter-spacing:.06em;text-transform:uppercase;cursor:pointer}.choices label:has(input[value=accept]:checked){border:2px solid var(--green);color:var(--green);background:var(--wash)}.choices label:has(input[value=change]:checked){border:2px solid var(--yellow);color:var(--yellow);background:var(--wash)}.choices label:has(input[value=reject]:checked){border:2px solid var(--red);color:var(--red);background:var(--wash)}.note-label{display:block;margin-top:1rem;font:500 11px/1.35 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--soft)}textarea{display:block;width:100%;min-height:4.5rem;margin-top:.4rem;padding:.6rem;resize:vertical;border:1px solid var(--rule);border-radius:0;background:var(--paper);color:var(--ink);font:400 14px/1.4 var(--mono)}textarea.error{border:2px solid var(--red)}.feedback-actions{display:flex;flex-wrap:wrap;gap:1rem;align-items:center;margin-top:2rem}button{min-height:44px;cursor:pointer;font:600 13px var(--mono);letter-spacing:.12em;text-transform:uppercase;border-radius:0}#copy{border:0;padding:.8rem 1.4rem;background:var(--ink);color:var(--paper);box-shadow:4px 4px 0 var(--route-hi)}#copy:active{transform:translate(2px,2px);box-shadow:2px 2px 0 var(--route-hi)}#status{margin:0;font:500 13px/1.4 var(--mono)}#status.success{color:var(--green)}#status.error{color:var(--red)}#fallback-label{width:100%;border-left:3px solid var(--yellow);padding-left:.6rem;font:500 11px var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--soft)}#clear-fallback{padding:.7rem 1rem;border:1px solid var(--ink);background:var(--paper);color:var(--ink)}.partial{margin-top:2rem;border:1px solid var(--ink);border-left:4px solid var(--yellow);padding:1.1rem 1.25rem}.incomplete-tag{color:var(--yellow)}:focus-visible{outline:2px solid var(--route);outline-offset:2px}summary:hover,.choices label:hover{color:var(--route);border-color:var(--route)}@media(max-width:520px){body{padding:1rem}.chart-head{grid-template-columns:1fr}.chart-head span:nth-child(2),.chart-head span:last-child{text-align:left}.metrics{grid-template-columns:1fr}.summary-line,.definition-grid p,.proof{grid-template-columns:1fr;gap:.25rem}.waypoint-group.now{padding-left:.75rem}}@media print{body{max-width:none;padding:.5in}fieldset,.feedback-actions{display:none}.chart-foot{margin-top:1rem}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style>'''
    output = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>{esc(roadmap['business'])} {esc(roadmap['date'])}</title>{css}</head><body>{header}{body}{footer}<script>{js}</script></body></html>'''
    sys.stdout.write(output)


if __name__ == '__main__':
    try: main()
    except (ValueError, json.JSONDecodeError) as error: raise SystemExit('invalid roadmap: ' + str(error))
